window.__trifold2Assets = {
  style: "<style>\n  html, body { margin: 0; height: 100%; background: #e5e5e5; }\n  a { color: #0A0A0A; }\n  a:hover { color: #ED7D31; }\n  * { box-sizing: border-box; }\n\n  #stage {\n    position: relative;\n    width: 100vw;\n    height: 100vh;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    overflow: hidden;\n    background: transparent;\n    user-select: none;\n    -webkit-user-select: none;\n  }\n\n  #canvas {\n    position: relative;\n    width: 1492px;\n    height: 1152px;\n    perspective: 2600px;\n    flex: none;\n    filter: drop-shadow(0 20px 60px rgba(0, 0, 0, 0.28));\n    overflow: hidden;\n  }\n\n  /* Fixed cover frame, anchored at the right edge of the canvas; never rotates */\n  #coverOuter {\n    position: absolute;\n    right: 0;\n    top: 0;\n    width: 498px;\n    height: 1152px;\n    overflow: visible;\n  }\n\n  /* Center panel: child of the cover frame, hinged at the cover's left edge */\n  #centerOuter {\n    position: absolute;\n    left: -496px;\n    top: 0;\n    width: 496px;\n    height: 1152px;\n    overflow: visible;\n    transform-style: preserve-3d;\n    transform-origin: 100% 50%;\n    backface-visibility: hidden;\n    transition: transform 1.3s cubic-bezier(0.22, 1, 0.36, 1);\n  }\n\n  /* Left panel: nested child of the center frame, hinged at the center's left edge (opposite rotation) */\n  #leftOuter {\n    position: absolute;\n    left: -498px;\n    top: 0;\n    width: 498px;\n    height: 1152px;\n    overflow: hidden;\n    transform-origin: 100% 50%;\n    backface-visibility: hidden;\n    transition: transform 1.3s cubic-bezier(0.22, 1, 0.36, 1);\n  }\n\n  #centerClip {\n    position: absolute;\n    left: 0;\n    top: 0;\n    width: 496px;\n    height: 1152px;\n    overflow: hidden;\n  }\n\n  #centerShadow, #coverShadow {\n    position: absolute;\n    left: 0;\n    top: 0;\n    width: 70px;\n    height: 100%;\n    pointer-events: none;\n    background: linear-gradient(to right, rgba(0, 0, 0, 0.55), rgba(0, 0, 0, 0));\n    transition: opacity 0.75s ease;\n  }\n\n  #coverOuter.dragging #centerOuter,\n  #coverOuter.dragging #leftOuter {\n    transition: none;\n  }\n  #coverOuter.dragging #centerShadow,\n  #coverOuter.dragging #coverShadow {\n    transition: none;\n  }\n\n  #coverClip {\n    position: absolute;\n    left: 0;\n    top: 0;\n    width: 498px;\n    height: 1152px;\n    overflow: hidden;\n    cursor: grab;\n    touch-action: none;\n  }\n  #coverClip.dragging { cursor: grabbing; }\n\n  #handle {\n    position: absolute;\n    left: -14px;\n    top: 50%;\n    transform: translateY(-50%);\n    width: 12px;\n    height: 64px;\n    border-radius: 8px;\n    background: #FFFFFF;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    gap: 4px;\n    transition: opacity 0.4s;\n    pointer-events: none;\n  }\n  #handle span {\n    width: 4px;\n    height: 4px;\n    border-radius: 50%;\n    background: #0A0A0A;\n    opacity: 0.4;\n  }\n\n  #hint {\n    position: absolute;\n    left: 0;\n    bottom: 24px;\n    width: 100%;\n    text-align: center;\n    font-family: 'Noto Sans TC', sans-serif;\n    font-size: 15px;\n    color: #555;\n    letter-spacing: 1px;\n    transition: opacity 0.4s;\n    pointer-events: none;\n  }\n\n  .poster {\n    position: absolute;\n    top: 0;\n    width: 1492px;\n    height: 1152px;\n    background: #CBE629;\n    overflow: hidden;\n    font-family: 'Noto Sans TC', sans-serif;\n  }\n</style>",
  markup: "<div id=\"stage\">\n  <div id=\"canvas\">\n\n    <div id=\"coverOuter\">\n\n      <div id=\"centerOuter\">\n\n        <div id=\"leftOuter\">\n          <div class=\"poster\" id=\"posterLeft\" style=\"left:0px;\"></div>\n        </div>\n\n        <div id=\"centerClip\">\n          <div class=\"poster\" id=\"posterCenter\" style=\"left:-498px;\"></div>\n          <div id=\"centerShadow\"></div>\n        </div>\n\n      </div>\n\n      <div id=\"coverClip\">\n        <div class=\"poster\" id=\"posterCover\" style=\"left:-994px;\"></div>\n        <div id=\"coverShadow\"></div>\n      </div>\n\n      <div id=\"handle\">\n        <span></span><span></span><span></span>\n      </div>\n\n    </div>\n\n  </div>\n\n  <div id=\"hint\">← 向左拖曳以展開 / Drag left to unfold</div>\n</div>"
};

